<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue'; import { Head,useForm } from '@inertiajs/vue3';
const props=defineProps({member:Object,account:Object,status:String,payments:Array});
const form=useForm({commencement_date:props.account.commencement_date?.slice(0,10)||'',plan:props.account.plan||'annual',exempt:!!props.account.exempt,annual_amount:Number(props.account.annual_amount_kobo||1250000)/100,monthly_amount:Number(props.account.monthly_amount_kobo||105000)/100,admin_note:props.account.admin_note||''});
function save(){form.put(`/admin/dues/${props.member.id}`)} function remind(){useForm({}).post(`/admin/dues/${props.member.id}/remind`)}
</script>
<template><PublicLayout><Head title="Manage Member Dues"/><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-8"><p class="text-xs font-bold uppercase tracking-widest text-[#D4A72C]">Administration</p><h1 class="mt-2 text-3xl font-extrabold text-white">Manage Member Dues</h1></div><AdminQuickLinks/></section><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-8"><p class="text-xs font-bold uppercase tracking-widest text-[#D4A72C]">Administration</p><h1 class="mt-2 text-3xl font-extrabold text-white">Manage Member Dues</h1></div><AdminQuickLinks/></section><div class="mx-auto max-w-5xl px-5 py-8"><a href="/admin/dues" class="text-sm font-bold text-[#006B3C]">← Back to dues</a><h1 class="mt-3 text-2xl font-extrabold text-[#00351F]">{{member.name}}</h1><p class="text-sm text-gray-500">{{member.email}} · {{member.member_status}}</p><div class="mt-6 rounded-xl border bg-white p-6"><div class="flex flex-wrap justify-between gap-3"><h2 class="text-lg font-bold">Dues settings</h2><button @click="remind" class="rounded-lg border px-4 py-2 text-sm font-bold">Send reminder</button></div><form @submit.prevent="save" class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm">Commencement date<input v-model="form.commencement_date" type="date" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="text-sm">Payment plan<select v-model="form.plan" class="mt-1 w-full rounded-lg border-gray-300"><option value="annual">Annual</option><option value="monthly">Monthly</option></select></label><label class="text-sm">Annual amount (₦)<input v-model="form.annual_amount" type="number" min="0" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="text-sm">Monthly amount (₦)<input v-model="form.monthly_amount" type="number" min="0" class="mt-1 w-full rounded-lg border-gray-300"/></label><label class="flex items-center gap-2 text-sm sm:col-span-2"><input v-model="form.exempt" type="checkbox"/> Exempt this member from dues</label><label class="text-sm sm:col-span-2">Admin note<textarea v-model="form.admin_note" class="mt-1 w-full rounded-lg border-gray-300" rows="3"/></label><button :disabled="form.processing" class="rounded-lg bg-[#006B3C] px-5 py-3 font-bold text-white sm:col-span-2">Save dues settings</button></form></div><div class="mt-6 rounded-xl border bg-white p-6"><h2 class="text-lg font-bold">Payment history</h2><div v-for="p in payments" :key="p.id" class="flex flex-wrap justify-between gap-2 border-b py-3 text-sm"><span>{{p.reference}} · {{p.period_type}} · {{p.method}}</span><b class="capitalize">{{p.status}} — ₦{{(p.amount_kobo/100).toLocaleString()}}</b></div><p v-if="!payments.length" class="mt-3 text-sm text-gray-500">No payments recorded.</p></div></div></PublicLayout></template>
